window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][24]={"university_physics_de:M24-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M24-L1 – Röntgenabschwächung, Bildkontrast und Dosis<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M6: elektromagnetische Felder; M7: Optik;\nM15: Wechselwirkung von Strahlung mit Materie. <a\nhref=\"index.html?course=university_physics&amp;module=M23&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorheriges Modul: M23-L7<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Einfaches Transmissionsmodell herleiten,\nHalbwertsdicke berechnen und absorbierte Dosis von Schutzgrößen\nunterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>Warum sind Knochen im Röntgenbild oft besser sichtbar als Weichteile?\nEine Röntgenquelle beleuchtet den Körper, und der Detektor misst die\ndurchgelassene Intensität. Unterschiedliche Materialien schwächen\nPhotonen unterschiedlich stark. Das Detektorsignal ist zunächst eine\nIntensitätsmessung, nicht unmittelbar eine räumliche Karte der\nbiologischen Wirkung. Auf dem Strahlenweg können Photoabsorption und\nStreuung zum Signalverlust oder zu einem verfälschten Bildkontrast\nbeitragen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>In einem engen, monoenergetischen und streuungsfreien Strahlenbündel\nist die Wahrscheinlichkeit einer Wechselwirkung in einer dünnen Schicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">dx<\/annotation><\/semantics><\/math>\nproportional zur verbleibenden Intensität. Aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>I<\/mi><mo>=<\/mo><mi>−<\/mi><mi>μ<\/mi><mi>I<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">dI=-\\mu I\\,dx<\/annotation><\/semantics><\/math>\nund Integration zwischen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>0<\/mn><annotation encoding=\"application/x-tex\">0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nfolgt das exponentielle Schwächungsgesetz. Die Halbwertsdicke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><annotation encoding=\"application/x-tex\">x_{1/2}<\/annotation><\/semantics><\/math>\nist jene Weglänge, bei der\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo>=<\/mo><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I=I_0/2<\/annotation><\/semantics><\/math>\ngilt. Die absorbierte Dosis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>D<\/mi><annotation encoding=\"application/x-tex\">D<\/annotation><\/semantics><\/math>\nist dagegen die in der Masse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>m<\/mi><annotation encoding=\"application/x-tex\">m<\/annotation><\/semantics><\/math>\ndeponierte Energie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">b<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">E_{\\mathrm{abs}}<\/annotation><\/semantics><\/math>\npro Masse, mit Einheit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">J<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{Gy}=1\\,\\mathrm{J/kg}<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>I<\/mi><mn>0<\/mn><\/msub><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>μ<\/mi><mi>x<\/mi><\/mrow><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>x<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mfrac><mrow><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><mi>μ<\/mi><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>D<\/mi><mo>=<\/mo><mfrac><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">b<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mi>m<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I(x)=I_0e^{-\\mu x},\\qquad x_{1/2}=\\frac{\\ln 2}{\\mu},\\qquad D=\\frac{E_{\\mathrm{abs}}}{m}.<\/annotation><\/semantics><\/math><\/p>\n<p>Für geschichtete Medien folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mi>/<\/mi><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><msub><mo>∑<\/mo><mi>j<\/mi><\/msub><msub><mi>μ<\/mi><mi>j<\/mi><\/msub><msub><mi>x<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">I/I_0=\\exp(-\\sum_j\\mu_j x_j)<\/annotation><\/semantics><\/math>;\nfür räumlich variables Material ersetzt ein Linienintegral die Summe.\nEin typisches diagnostisches Spektrum ist nicht monoenergetisch:\nEnergieabhängigkeit von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>μ<\/mi><annotation encoding=\"application/x-tex\">\\mu<\/annotation><\/semantics><\/math>\nführt zur Strahlaufhärtung. Absorbierte Dosis (Gy) und effektive Dosis\n(Sv) sind unterschiedliche Größen; aus einem bloßen Detektorwert kann\nkeine individuelle biologische Gefährdung berechnet werden. Die\nBildqualität hängt außerdem von Quantenzahl, Streuung,\nDetektoreigenschaften und Verarbeitung ab.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mu=0{,}20\\,\\mathrm{cm^{-1}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>5<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x=5{,}0\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mi>x<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mu x=1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mi>/<\/mi><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>368<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I/I_0=e^{-1}\\approx0{,}368<\/annotation><\/semantics><\/math>.\nDie Halbwertsdicke beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mi>/<\/mi><mn>0<\/mn><mo>,<\/mo><mn>20<\/mn><mo>≈<\/mo><mn>3<\/mn><mo>,<\/mo><mn>47<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x_{1/2}=\\ln2/0{,}20\\approx3{,}47\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>.\nBei gleichmäßig angenommener Aufnahme von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>020<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">J<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0{,}020\\,\\mathrm J<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">2{,}0\\,\\mathrm{kg}<\/annotation><\/semantics><\/math>\nwäre\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>010<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">D=0{,}010\\,\\mathrm{Gy}<\/annotation><\/semantics><\/math>.\nDie Zeichnung zeigt ausschließlich ein hypothetisches Material und eine\nmathematische Modellkurve.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_321_DE.svg\"\nalt=\"Schematische Röntgenquelle, durchstrahlte Schicht und Detektor neben einer exponentiell fallenden normierten Intensitätskurve.\" />\n<figcaption aria-hidden=\"true\">Schematische Röntgenquelle, durchstrahlte\nSchicht und Detektor neben einer exponentiell fallenden normierten\nIntensitätskurve.<\/figcaption>\n<\/figure>\n<p><em>Eigene Modellzeichnung für monoenergetische, streuungsfreie\nTransmission; keine Patientendaten.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mi>/<\/mi><msub><mi>I<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">I/I_0<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mi>x<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mu x=\\ln2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><annotation encoding=\"application/x-tex\">x_{1/2}<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mu=0{,}10\\,\\mathrm{cm^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist eine Dosis von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{Gy}<\/annotation><\/semantics><\/math>\nnicht dasselbe wie eine Angabe von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">S<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{Sv}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mi>/<\/mi><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I/I_0=1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>693<\/mn><mi>/<\/mi><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><mo>≈<\/mo><mn>6<\/mn><mo>,<\/mo><mn>93<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x_{1/2}=0{,}693/0{,}10\\approx6{,}93\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die erste Größe misst deponierte Energie je Masse; eine Schutzgröße\nin Sv berücksichtigt weitere Definitionen und Gewichtungen und ist nicht\nallein aus Gy ableitbar.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Modell vernachlässigt Spektrum, Mehrfachstreuung und Geometrie.\nDie Beispielwerte sind frei gewählt und kein klinisches\nUntersuchungsprotokoll. Für medizinische Entscheidungen gelten\nfachgerechte Rechtfertigung und Optimierung sowie geprüfte dosimetrische\nGrößen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Röntgenabschwächung ist eine Überlagerung von Strahlenweg und\nMaterialeigenschaften; absorbierte Dosis ist eine davon begrifflich\ngetrennte Energiedosis.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Computertomographie, Projektionen\nund Rückprojektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/3edwt-0rf59\">IAEA INIS – Diagnostic radiology physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–23; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L1 – Röntgenabschwächung, Bildkontrast und Dosis · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://nucleus.iaea.org/Pages/rpop.aspx\">IAEA NUCLEUS – Radiation Protection of Patients<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 32–38; thematische Quellenzuordnung; Fachlicher Bezug zur Lektion: M24-L1 – Röntgenabschwächung, Bildkontrast und Dosis · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M24-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M24-L2 – Computertomographie, Projektionen und Rückprojektion<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M7: Strahlenoptik; M8:\nFouriertransformation; M17: numerische Verfahren. <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Von Röntgentransmission zur Projektion\ngelangen und erklären, weshalb reine Rückprojektion unscharf ist.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>Die konventionelle Röntgenaufnahme überlagert alle\nAbschwächungsbeiträge eines Strahlenwegs. In der Computertomographie\nwerden Projektionen aus vielen Richtungen gesammelt. So kann aus einer\nVielzahl eindimensionaler Linienintegrale eine zweidimensionale\nSchwächungsverteilung rekonstruiert werden. Die entscheidende Frage ist\nnicht nur, wie viele Messungen vorliegen, sondern welche Winkel und\nOrtsfrequenzen sie erfassen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>Bei monoenergetischer und streuungsfreier Strahlung ist der negative\nLogarithmus der normierten Intensität ein Linienintegral des lokalen\nSchwächungskoeffizienten. Für einen Parallelstrahl mit Winkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>θ<\/mi><annotation encoding=\"application/x-tex\">\\theta<\/annotation><\/semantics><\/math>\nund Detektorabstand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>s<\/mi><annotation encoding=\"application/x-tex\">s<\/annotation><\/semantics><\/math>\nbeschreibt die Radon-Transformation diese Sammlung von Integralen. Der\nFourier-Schnitt-Satz verknüpft die eindimensionale Fouriertransformation\nvon\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>θ<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">p_\\theta(s)<\/annotation><\/semantics><\/math>\nmit einem radialen Schnitt der zweidimensionalen Fouriertransformierten\nvon\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mu(x,y)<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>θ<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>−<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><msub><mi>I<\/mi><mi>θ<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><msub><mi>I<\/mi><mn>0<\/mn><\/msub><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>=<\/mo><msub><mo>∫<\/mo><mrow><mi>ℓ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo>,<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msub><mspace width=\"-0.167em\"><\/mspace><mi>μ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>l<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p_\\theta(s)=-\\ln\\!\\left(\\frac{I_\\theta(s)}{I_0}\\right)=\\int_{\\ell(\\theta,s)}\\!\\mu(x,y)\\,dl.<\/annotation><\/semantics><\/math><\/p>\n<p>Bei ungefilterter Rückprojektion werden die Projektionswerte entlang\nder ursprünglichen Strahlenpfade verteilt; dadurch bleiben tiefe\nOrtsfrequenzen überbetont und scharfe Kanten verwischen. Im idealen\nkontinuierlichen 2D-Parallelstrahlfall multipliziert die gefilterte\nRückprojektion die Fouriertransformierte jeder Projektion mit einem\nRampenfilter proportional\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\omega|<\/annotation><\/semantics><\/math>\nund integriert die gefilterten Projektionen über\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>≤<\/mo><mi>θ<\/mi><mo>&lt;<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0\\le\\theta&lt;\\pi<\/annotation><\/semantics><\/math>.\nNormierungsfaktoren hängen von der Fourierkonvention ab. In realen\nScannern verlangen Kegelstrahl-, Fächerstrahlgeometrie, statistische\nDetektoren, Streuung und Metallartefakte angepasste Modelle.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Eine ideale Projektion mit Linienintegral\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>80<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}80<\/annotation><\/semantics><\/math>\nwürde eine normierte Intensität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mi>/<\/mi><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>0<\/mn><mo>,<\/mo><mn>8<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>449<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I/I_0=e^{-0{,}8}\\approx0{,}449<\/annotation><\/semantics><\/math>\nergeben. Liegt die Linie durch zwei homogene Abschnitte mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>μ<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mu_1=0{,}10\\,\\mathrm{cm^{-1}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x_1=3\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>μ<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mu_2=0{,}25\\,\\mathrm{cm^{-1}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x_2=2\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>,\ndann ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>30<\/mn><mo>+<\/mo><mn>0<\/mn><mo>,<\/mo><mn>50<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>80<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}30+0{,}50=0{,}80<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt eine gedachte Strahlensammlung und vergleicht\nkonzeptuell Rückprojektion und Filterung.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_062_DE.svg\"\nalt=\"Rotierende gedachte Röntgenquelle mit mehreren Strahlen, Sinogrammstreifen und Vergleich einer verwischten mit einer geschärften Phantomkontur.\" />\n<figcaption aria-hidden=\"true\">Rotierende gedachte Röntgenquelle mit\nmehreren Strahlen, Sinogrammstreifen und Vergleich einer verwischten mit\neiner geschärften Phantomkontur.<\/figcaption>\n<\/figure>\n<p><em>Schematische Parallelstrahl-CT.<\/em><\/p>\n<p>Keine klinischen Rohdaten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Transmission gehört zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=\\ln4<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>12<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mu=0{,}12\\,\\mathrm{cm^{-1}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x=5\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum verstärkt der Rampenfilter bei endlichen Zählstatistiken\nzugleich Rauschen?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mi>/<\/mi><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>4<\/mn><\/mrow><\/msup><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I/I_0=e^{-\\ln4}=0{,}25<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>12<\/mn><mo>⋅<\/mo><mn>5<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>60<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}12\\cdot5=0{,}60<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Hohe Ortsfrequenzen erhalten bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\omega|<\/annotation><\/semantics><\/math>\ngrößeres Gewicht; Messrauschen im Hochfrequenzbereich wird\nmitverstärkt.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Herleitung behandelt ideale Parallelstrahlen in einer einzelnen\nEbene. Klinische CT-Systeme müssen Spektralaufhärtung, Streustrahlung,\nendliche Winkelabtastung, Detektorkalibration und\nRekonstruktionsalgorithmus berücksichtigen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Projektion ist der negative Logarithmus der Transmission. Die\nRekonstruktion benötigt ein geometrisch korrektes Vorwärtsmodell und\neine kontrollierte Inversion.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Magnetresonanztomographie,\nLarmorfrequenz und k-Raum<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://lme.tf.fau.de/lecture-notes/lecture-notes-me/computed-tomography-reconstruction/\">FAU – FAU Pattern Recognition Lab – Computed Tomography: Reconstruction<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Zeilen 55–87 und 102–103; Fachlicher Bezug zur Lektion: M24-L2 – Computertomographie, Projektionen und Rückprojektion · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/3edwt-0rf59\">IAEA INIS – Diagnostic radiology physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–23; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L2 – Computertomographie, Projektionen und Rückprojektion · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M24-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M24-L3 – Magnetresonanztomographie, Larmorfrequenz und k-Raum<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M6: Magnetfelder; M11: Kernspin; M8:\nFouriertransformation. <a href=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Frequenz und Ortskodierung in einer\nidealisierten MRT-Sequenz berechnen und k-Raum-Daten von Bildpunkten\nunterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>Magnetresonanztomographie detektiert Signale von Kernspins in einem\nstarken statischen Magnetfeld. Anders als Röntgen und CT nutzt sie keine\nionisierende Röntgenstrahlung. Das statische Feld ordnet die\nKernmagnetisierung; ein passender Hochfrequenzpuls kann sie auslenken.\nWährend die Spins präzedieren und relaxieren, induziert die zeitlich\nveränderliche Magnetisierung ein Empfangssignal in einer Spule.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>Für einen Spin mit gyromagnetischem Verhältnis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nist die Larmor-Kreisfrequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>B<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\omega_0=|\\gamma|B_0<\/annotation><\/semantics><\/math>.\nDie Frequenz in Hertz unterscheidet sich um den Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>.\nEin zeitabhängiger Magnetfeldgradient\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"bold-italic\">𝑮<\/mi><annotation encoding=\"application/x-tex\">\\mathbf G<\/annotation><\/semantics><\/math>\nerzeugt ortsabhängige Phasen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>γ<\/mi><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><mi mathvariant=\"bold-italic\">𝑮<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>τ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"-0.167em\"><\/mspace><mo>⋅<\/mo><mspace width=\"-0.167em\"><\/mspace><mi mathvariant=\"bold-italic\">𝒓<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>τ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\phi(\\mathbf r,t)=\\gamma\\int_0^t\\mathbf G(\\tau)\\!\\cdot\\!\\mathbf r\\,d\\tau<\/annotation><\/semantics><\/math>.\nDamit wird die Phase nach geeigneter Sequenzdefinition zur\nFourier-Ortskodierung, beschrieben durch den k-Raum-Vektor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf k(t)<\/annotation><\/semantics><\/math>.\nDas Vorzeichen folgt der jeweiligen Definition von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nund des komplexen Empfangssignals.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>B<\/mi><mn>0<\/mn><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>f<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>B<\/mi><mn>0<\/mn><\/msub><\/mrow><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mi>γ<\/mi><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><\/mfrac><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><mi mathvariant=\"bold-italic\">𝑮<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>τ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>τ<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega_0=|\\gamma|B_0,\\qquad f_0=\\frac{|\\gamma|B_0}{2\\pi},\\qquad \\mathbf k(t)=\\frac{\\gamma}{2\\pi}\\int_0^t\\mathbf G(\\tau)\\,d\\tau.<\/annotation><\/semantics><\/math><\/p>\n<p>Im einfachen 2D-Modell ergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo>∫<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>i<\/mi><mn>2<\/mn><mi>π<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi>d<\/mi><mn>2<\/mn><\/msup><mi>r<\/mi><\/mrow><annotation encoding=\"application/x-tex\">s(\\mathbf k)=\\int \\rho(\\mathbf r)e^{-i2\\pi\\mathbf k\\cdot\\mathbf r}\\,d^2r<\/annotation><\/semantics><\/math>,\nwobei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ρ<\/mi><annotation encoding=\"application/x-tex\">\\rho<\/annotation><\/semantics><\/math>\neine effektive spin- und sequenzgewichtete Signaldichte ist. Reale\nEmpfangsdaten enthalten T1-, T2-, Suszeptibilitäts-, Bewegungseffekte,\nSpulenprofile und Rauschen. Der k-Raum ist der Raum der räumlichen\nFrequenzen und nicht bereits ein anatomisches Bild; erst eine geeignete\ninverse Fouriertransformation liefert das vereinfachte Ortsbild.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für Protonen beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mn>42<\/mn><mo>,<\/mo><mn>58<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">T<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">|\\gamma|/(2\\pi)\\approx42{,}58\\,\\mathrm{MHz/T}<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>3<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B_0=3{,}0\\,\\mathrm T<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mn>0<\/mn><\/msub><mo>≈<\/mo><mn>127<\/mn><mo>,<\/mo><mn>7<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">f_0\\approx127{,}7\\,\\mathrm{MHz}<\/annotation><\/semantics><\/math>.\nEin konstanter Gradient\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">T<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">G=1{,}0\\,\\mathrm{mT/m}<\/annotation><\/semantics><\/math>\nüber\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1{,}0\\,\\mathrm{ms}<\/annotation><\/semantics><\/math>\nführt zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>≈<\/mo><mn>42<\/mn><mo>,<\/mo><mn>6<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k\\approx42{,}6\\,\\mathrm{m^{-1}}<\/annotation><\/semantics><\/math>\nin der entsprechenden Achse. Die Grafik zeigt präzedierende\nMagnetisierung und den schematischen Übergang von k-Raum-Abtastung zum\nBild.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_185_DE.svg\"\nalt=\"Präzedierende Magnetisierung im statischen Feld und schematische Messpunkte in einem k-Raum-Raster mit zugehöriger Ortsbilddarstellung.\" />\n<figcaption aria-hidden=\"true\">Präzedierende Magnetisierung im\nstatischen Feld und schematische Messpunkte in einem k-Raum-Raster mit\nzugehöriger Ortsbilddarstellung.<\/figcaption>\n<\/figure>\n<p><em>Konzeptionelle MRT-Skizze ohne Messsignale oder\nPatientendaten.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>f<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">f_0<\/annotation><\/semantics><\/math>\nfür Protonen bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B_0=1{,}5\\,\\mathrm T<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welches\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\nfolgt bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">T<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">G=2\\,\\mathrm{mT/m}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t=1\\,\\mathrm{ms}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>ω<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\omega_0<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{rad/s}<\/annotation><\/semantics><\/math>\nnicht numerisch gleich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>f<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">f_0<\/annotation><\/semantics><\/math>\nin Hertz?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mn>0<\/mn><\/msub><mo>≈<\/mo><mn>42<\/mn><mo>,<\/mo><mn>58<\/mn><mo>⋅<\/mo><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><mo>=<\/mo><mn>63<\/mn><mo>,<\/mo><mn>9<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">f_0\\approx42{,}58\\cdot1{,}5=63{,}9\\,\\mathrm{MHz}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>≈<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>42<\/mn><mo>,<\/mo><mn>58<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mn>6<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>⋅<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>002<\/mn><mo>⋅<\/mo><mn>0<\/mn><mo>,<\/mo><mn>001<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mn>85<\/mn><mo>,<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k\\approx(42{,}58\\cdot10^6)\\cdot(0{,}002\\cdot0{,}001)\\approx85{,}2\\,\\mathrm{m^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weil eine volle Umdrehung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>\nRadiant umfasst:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><msub><mi>f<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\omega_0=2\\pi f_0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Fouriermodell nimmt eine idealisierte Sequenz, gleiche\nEmpfangsempfindlichkeit und korrigierte statische Feldinhomogenität an.\nDie Beispielrechnung enthält weder patientenbezogene Sicherheitsgrenzen\nnoch Aussagen zur diagnostischen Bildqualität.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>MRT-Ortsinformationen entstehen aus gezielten Phasengradienten. Die\nFaktor-2π-Konvention ist für die korrekte Interpretation des k-Raums\nzwingend.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Ultraschall, Puls-Echo-Methode und\nSchallimpedanz<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://socr.umich.edu/BPAD1/BPAD1_notes/BPAD1_Chap04_MRI.html\">University of Michigan – Biomedical Physics with Applications to Disease, Chapter 4: MRI<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Gl. 6, 17–21; Z. 166–170, 546–570; Fachlicher Bezug zur Lektion: M24-L3 – Magnetresonanztomographie, Larmorfrequenz und k-Raum · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/3edwt-0rf59\">IAEA INIS – Diagnostic radiology physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–23; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L3 – Magnetresonanztomographie, Larmorfrequenz und k-Raum · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M24-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M24-L4 – Ultraschall, Puls-Echo-Methode und Schallimpedanz<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M4: Schallwellen und Reflexion; M16:\nMessunsicherheit. <a href=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die Laufzeit-Tiefenformel herleiten,\nIntensitätsreflexion aus Impedanzen berechnen und Modellgrenzen\nangeben.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>Ein Ultraschallwandler sendet kurze akustische Pulse in ein Medium.\nAn Grenzen unterschiedlicher akustischer Eigenschaften entstehen\nreflektierte Echoanteile, deren Laufzeit und Stärke gemessen werden. Ein\nB-Bild ordnet Echoamplituden einer Tiefe und Strahlrichtung zu; die\nHelligkeit ist deshalb keine direkte Materialdichtekarte. Verschiedene\nEchozeiten entstehen auch durch unterschiedlich lange\nAusbreitungswege.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>Legt ein Puls den Weg zur reflektierenden Grenzfläche und zurück bei\nangenommener konstanter Schallgeschwindigkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>c<\/mi><annotation encoding=\"application/x-tex\">c<\/annotation><\/semantics><\/math>\nin der Zeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>t<\/mi><annotation encoding=\"application/x-tex\">t<\/annotation><\/semantics><\/math>\nzurück, gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>d<\/mi><mo>=<\/mo><mi>c<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2d=ct<\/annotation><\/semantics><\/math>.\nDie akustische Impedanz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Z<\/mi><mo>=<\/mo><mi>ρ<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z=\\rho c<\/annotation><\/semantics><\/math>\nist das Produkt aus Massendichte und Schallgeschwindigkeit. Für eine\nebene Grenzfläche, senkrechten Einfall und verlustlose Medien gilt für\nden reflektierten Intensitätsanteil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>I<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_I<\/annotation><\/semantics><\/math>\ndie quadratische Impedanzformel. Der Amplitudenreflexionskoeffizient ist\nohne Quadrat und kann ein Vorzeichen besitzen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mfrac><mrow><mi>c<\/mi><mi>t<\/mi><\/mrow><mn>2<\/mn><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>Z<\/mi><mo>=<\/mo><mi>ρ<\/mi><mi>c<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>R<\/mi><mi>I<\/mi><\/msub><mo>=<\/mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><mo>−<\/mo><msub><mi>Z<\/mi><mn>1<\/mn><\/msub><\/mrow><mrow><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><mo>+<\/mo><msub><mi>Z<\/mi><mn>1<\/mn><\/msub><\/mrow><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">d=\\frac{ct}{2},\\qquad Z=\\rho c,\\qquad R_I=\\left(\\frac{Z_2-Z_1}{Z_2+Z_1}\\right)^2.<\/annotation><\/semantics><\/math><\/p>\n<p>Eine angenommene Weichteilgeschwindigkeit von etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1540<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1540\\,\\mathrm{m/s}<\/annotation><\/semantics><\/math>\ndient vielen Lehrmodellen, ist aber kein für alle Gewebe gültiger\nMesswert. Inhomogene Geschwindigkeiten bewirken Tiefenfehler. Die axiale\nAuflösung verbessert sich bei kürzeren Pulsen; höhere Frequenz erhöht in\nvielen Geweben zugleich die Dämpfung. Laterale Auflösung hängt\nwesentlich von Wandlerapertur, Fokussierung und Beugung ab. Nicht jede\nGrenzfläche liegt senkrecht zur Schallausbreitung.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>100<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">t=100\\,\\mathrm{\\mu s}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mn>1540<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">c=1540\\,\\mathrm{m/s}<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1540<\/mn><mo>⋅<\/mo><mn>100<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>6<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>077<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mo>=<\/mo><mn>7<\/mn><mo>,<\/mo><mn>7<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">d=(1540\\cdot100\\cdot10^{-6})/2=0{,}077\\,\\mathrm m=7{,}7\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>50<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Z_1=1{,}50<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>65<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Z_2=1{,}65<\/annotation><\/semantics><\/math>\nin gleichen MRayl-Einheiten ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>I<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>15<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mn>15<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>00227<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R_I=(0{,}15/3{,}15)^2\\approx0{,}00227<\/annotation><\/semantics><\/math>,\nalso etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>227<\/mn><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0{,}227\\%<\/annotation><\/semantics><\/math>.\nDie Skizze trennt Echo-Laufzeit und Grenzflächenreflexion.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_303_DE.svg\"\nalt=\"Schallkopf, hinlaufender Schallpuls, Echo an einer Grenzfläche und zeitlich getrennte Sende- und Empfangsspitzen.\" />\n<figcaption aria-hidden=\"true\">Schallkopf, hinlaufender Schallpuls, Echo\nan einer Grenzfläche und zeitlich getrennte Sende- und\nEmpfangsspitzen.<\/figcaption>\n<\/figure>\n<p><em>Eigene Illustration eines idealisierten\nPuls-Echo-Versuchs.<\/em><\/p>\n<p>Keine klinischen Ultraschalldaten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne die Tiefe für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>80<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">t=80\\,\\mathrm{\\mu s}<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mn>1540<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">c=1540\\,\\mathrm{m/s}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>I<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_I<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Z_1=Z_2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist eine angenommene konstante Geschwindigkeit eine mögliche\nFehlerquelle?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mn>1540<\/mn><mo>⋅<\/mo><mn>80<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>6<\/mn><\/mrow><\/msup><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0616<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mo>=<\/mo><mn>6<\/mn><mo>,<\/mo><mn>16<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">d=1540\\cdot80\\cdot10^{-6}/2=0{,}0616\\,\\mathrm m=6{,}16\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>I<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R_I=0<\/annotation><\/semantics><\/math>,\nes gibt bei idealer Anpassung keine Reflexion durch den\nImpedanzsprung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Reale Schallwege durchlaufen Medien mit unterschiedlichen\nGeschwindigkeiten; die Formel ordnet dann die gemessene Laufzeit einer\nfalschen Tiefe zu.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Intensitätsformel setzt ebene Wellen, Normaleinfall und\nverlustfreie Grenzflächen voraus. Mehrwegeausbreitung, Streuung,\nSpeckle, Absorption und Schallgeschwindigkeitsgradienten erfordern\naufwendigere Signalmodelle.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Puls-Echo-Tiefe enthält den Faktor 1/2 für den Rückweg. Der\nReflexionskontrast ist bei idealem Normaleinfall durch den\nImpedanzsprung bestimmt.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nuklearmedizinische Bildgebung: PET\nund SPECT<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://dbauer.physics.ucla.edu/5b/23-ultrasound/\">UCLA – UCLA – Physics 5B, Ultrasound<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 63–80, 84–99; Fachlicher Bezug zur Lektion: M24-L4 – Ultraschall, Puls-Echo-Methode und Schallimpedanz · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/3edwt-0rf59\">IAEA INIS – Diagnostic radiology physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–23; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L4 – Ultraschall, Puls-Echo-Methode und Schallimpedanz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M24-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M24-L5 – Nuklearmedizinische Bildgebung: PET und SPECT<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M15: Kernzerfälle und\nStrahlungsdetektoren; M13: Zählstatistik. <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Detektionsprinzipien von PET und SPECT\nunterscheiden und eine idealisierte Koinzidenz- und Zählstatistik\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>PET und SPECT nutzen die Verteilung radioaktiv markierter Substanzen\nals Bildinformation. Beide Verfahren erfassen emittierte Strahlung,\nstatt wie ein Röntgengerät einen von außen erzeugten Strahl durch den\nKörper zu messen. Die Aufnahme liefert Aktivitätsverteilungen mit\nkomplexen Korrekturen für Zerfall, Schwächung, Streuung und\nDetektoreigenschaften. Eine erhöhte Aktivität ist ohne den fachlichen\nKontext keine eindeutige Diagnose.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>Bei der Positronen-Emissions-Tomographie annihiliert ein Positron\nnach seiner Abbremsung mit einem Elektron. Bei näherungsweise ruhendem\nPaar entstehen zwei Photonen von jeweils\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m<\/mi><mi>e<\/mi><\/msub><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>≈<\/mo><mn>511<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">m_ec^2\\approx511\\,\\mathrm{keV}<\/annotation><\/semantics><\/math>\nin fast entgegengesetzte Richtungen. Zwei zeitlich gekoppelte\nDetektorsignale definieren eine sogenannte line of response (LOR). In\neiner idealen Time-of-Flight-Messung ergibt eine Laufzeitdifferenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t<\/annotation><\/semantics><\/math>\neine Ortsverschiebung entlang der LOR von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo>≈<\/mo><mi>c<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta x\\approx c\\Delta t/2<\/annotation><\/semantics><\/math>.\nIn SPECT wird die Richtung eines einzelnen Gammaphotons häufig mit einem\nmechanischen Kollimator eingeschränkt.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>γ<\/mi><\/msub><mo>=<\/mo><msub><mi>m<\/mi><mi>e<\/mi><\/msub><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>≈<\/mo><mn>511<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo>≈<\/mo><mfrac><mrow><mi>c<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><\/mrow><mn>2<\/mn><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mfrac><msub><mi>σ<\/mi><mi>N<\/mi><\/msub><mi>N<\/mi><\/mfrac><mo>≈<\/mo><mfrac><mn>1<\/mn><msqrt><mi>N<\/mi><\/msqrt><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E_\\gamma=m_ec^2\\approx511\\,\\mathrm{keV},\\qquad \\Delta x\\approx\\frac{c\\,\\Delta t}{2},\\qquad \\frac{\\sigma_N}{N}\\approx\\frac{1}{\\sqrt N}.<\/annotation><\/semantics><\/math><\/p>\n<p>Die beiden PET-Photonen sind aufgrund endlicher Impulse nicht exakt\nantiparallel; zudem verwischen Positronenreichweite, Streuung, zufällige\nKoinzidenzen und Detektorzeitauflösung die Lokalisierung. Die\nSPECT-Photonenergie hängt vom verwendeten Nuklid ab und ist nicht\ngenerell 511 keV. Für unabhängige Poisson-Zählungen mit Mittelwert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nist die Standardabweichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>N<\/mi><\/msub><mo>≈<\/mo><msqrt><mi>N<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_N\\approx\\sqrt N<\/annotation><\/semantics><\/math>\nund die relative Streuung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><msqrt><mi>N<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">1/\\sqrt N<\/annotation><\/semantics><\/math>.\nDas ist eine Modellregel zur Statistik, kein allgemeiner Grenzwert für\nBildqualität.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei einer angenommenen Zeitauflösung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>200<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t=200\\,\\mathrm{ps}<\/annotation><\/semantics><\/math>\nist die räumliche Unschärfeskala\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mi>/<\/mi><mn>2<\/mn><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>030<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mo>=<\/mo><mn>3<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">c\\Delta t/2\\approx0{,}030\\,\\mathrm m=3{,}0\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mn>000<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=10\\,000<\/annotation><\/semantics><\/math>\nunabhängige erwartete Ereignisse ist die relative Poisson-Unsicherheit\nungefähr\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\%<\/annotation><\/semantics><\/math>.\nDie Grafik kontrastiert die PET-Koinzidenzlinie mit SPECT-Kollimation.\nSie zeigt kein realistisch aufgelöstes Patientensignal.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_206_DE.svg\"\nalt=\"Links zwei gegenüberliegende PET-Detektoren an einer Koinzidenzlinie, rechts ein SPECT-Kollimator vor einem Einzelphotondetektor.\" />\n<figcaption aria-hidden=\"true\">Links zwei gegenüberliegende\nPET-Detektoren an einer Koinzidenzlinie, rechts ein SPECT-Kollimator vor\neinem Einzelphotondetektor.<\/figcaption>\n<\/figure>\n<p><em>Eigene schematische Darstellung der\nDetektionsprinzipien.<\/em><\/p>\n<p>Keine Bilddaten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta x<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>100<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t=100\\,\\mathrm{ps}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>N<\/mi><\/msub><mi>/<\/mi><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_N/N<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>400<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=400<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf die Energie von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>511<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">511\\,\\mathrm{keV}<\/annotation><\/semantics><\/math>\nnicht pauschal jeder SPECT-Aufnahme zugeordnet werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo>=<\/mo><mn>3<\/mn><mo>,<\/mo><mn>0<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mn>8<\/mn><\/msup><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>10<\/mn><\/mrow><\/msup><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>015<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta x=3{,}0\\cdot10^8\\cdot10^{-10}/2=0{,}015\\,\\mathrm m=1{,}5\\,\\mathrm{cm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><msqrt><mn>400<\/mn><\/msqrt><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>05<\/mn><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/\\sqrt{400}=0{,}05=5\\,\\%<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">SPECT registriert Photonen nuklidabhängiger Emissionen; 511 keV\nkennzeichnet die Annihilationsphotonen bei der PET.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das TOF-Modell setzt einen vereinfachten Photonenweg voraus. Reale\nRekonstruktion und Dosimetrie erfordern Korrekturen und klinische\nValidierung. Das Beispiel ist keine Qualitäts- oder Dosisempfehlung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>PET lokalisiert Koinzidenzen entlang einer Detektorverbindung; SPECT\nnutzt häufig kollimierte Einzelphotonen. Zählstatistik begrenzt die\nPräzision beider Messarten.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Rekonstruktion, Auflösung, Rauschen\nund Artefakte<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://socr.umich.edu/BPAD1/BPAD1_notes/BPAD1_Chap06_NuclearMedicine_PET_SPECT.html\">University of Michigan – Biomedical Physics with Applications to Disease, Chapter 6: Nuclear Medicine, PET and SPECT<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Abschn. 6.4–6.5.2; Z. 439, 451–465; Fachlicher Bezug zur Lektion: M24-L5 – Nuklearmedizinische Bildgebung: PET und SPECT · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/sy9wq-mvk34\">IAEA INIS – Nuclear Medicine Physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–15; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L5 – Nuklearmedizinische Bildgebung: PET und SPECT · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://nucleus.iaea.org/Pages/rpop.aspx\">IAEA NUCLEUS – Radiation Protection of Patients<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 32–38; thematische Quellenzuordnung; Fachlicher Bezug zur Lektion: M24-L5 – Nuklearmedizinische Bildgebung: PET und SPECT · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M24-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M24-L6 – Rekonstruktion, Auflösung, Rauschen und Artefakte<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M8: Faltung und Fouriertransformation;\nM16: Fehlerfortpflanzung; M17: Inverse Probleme. <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Bildschärfe, Kontrast, Rauschen und\nArtefakte quantitativ und methodisch voneinander abgrenzen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>Medizinische Messgeräte erzeugen zunächst Rohsignale. Erst ein\nphysikalisches Vorwärtsmodell und ein Rekonstruktionsverfahren\nüberführen sie in eine Bilddarstellung. Zwei Bilder desselben Objekts\nkönnen sich in Rauschen und scheinbarer Schärfe stark unterscheiden,\nobwohl die Messung an derselben Struktur vorgenommen wurde. Eine\naggressive Schärfung kann allerdings auch Artefakte erzeugen. Deshalb\nreicht ein optisch angenehmes Bild als Qualitätsmaß nicht aus.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>In einem näherungsweise ortsinvarianten, linearen Modell wird die\nwahre Objektverteilung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(\\mathbf r)<\/annotation><\/semantics><\/math>\ndurch die Punktspreizfunktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">h(\\mathbf r)<\/annotation><\/semantics><\/math>\ngefaltet; zusätzlich tritt Rauschen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">n(\\mathbf r)<\/annotation><\/semantics><\/math>\nauf. Die Faltung glättet Kanten und reduziert hohe Ortsfrequenzen. Für\nzwei unabhängige gaußförmige Unschärfen mit Standardabweichungen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>σ<\/mi><mn>1<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\sigma_1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>σ<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\sigma_2<\/annotation><\/semantics><\/math>\naddieren sich die Varianzen. Bei einer idealen Poisson-Zählung mit\nErwartungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nist das Verhältnis Mittelwert zu Standardabweichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mi>/<\/mi><msqrt><mi>N<\/mi><\/msqrt><mo>=<\/mo><msqrt><mi>N<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">N/\\sqrt N=\\sqrt N<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo>*<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mrow><mi mathvariant=\"normal\">S<\/mi><mi mathvariant=\"normal\">N<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mo>≈<\/mo><msqrt><mi>N<\/mi><\/msqrt><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msubsup><mi>σ<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><msubsup><mi>σ<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>σ<\/mi><mn>2<\/mn><mn>2<\/mn><\/msubsup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">g(\\mathbf r)=(h*f)(\\mathbf r)+n(\\mathbf r),\\qquad \\mathrm{SNR}_{\\mathrm{counts}}\\approx\\sqrt N,\\qquad \\sigma_{\\mathrm{tot}}^2=\\sigma_1^2+\\sigma_2^2.<\/annotation><\/semantics><\/math><\/p>\n<p>Die Zählformel gilt nicht allgemein für bildrekonstruierte Pixel:\nNach Filterung oder iterativer Rekonstruktion sind Rauschen und\nBildpunkte häufig korreliert. Die Übertragungsfunktion und das\nAbtastraster beeinflussen die räumliche Auflösung; bewegte Objekte oder\nfalsche Modellannahmen erzeugen weitere Artefakte. Wird die Photonenzahl\nverändert, kann dies Exposition, Aufnahmezeit oder Traceraktivität\nbetreffen; ohne medizinische Begründung ist eine reine Maximierung der\nStatistik unzulässig.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Ein synthetischer Detektor zählt im Mittel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>400<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=400<\/annotation><\/semantics><\/math>\nEreignisse:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>N<\/mi><\/msub><mo>≈<\/mo><mn>20<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_N\\approx20<\/annotation><\/semantics><\/math>\nund die relative Standardabweichung beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">5\\,\\%<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>1600<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=1600<\/annotation><\/semantics><\/math>\nwären es\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>40<\/mn><annotation encoding=\"application/x-tex\">40<\/annotation><\/semantics><\/math>\nEreignisse bzw.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2{,}5\\,\\%<\/annotation><\/semantics><\/math>\nrelativ: viermal mehr Ereignisse halbieren die relative Unsicherheit.\nHaben zwei unabhängige gaußförmige Unschärfen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_1=1\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_2=2\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>,\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>=<\/mo><msqrt><mn>5<\/mn><\/msqrt><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>24<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_{\\mathrm{tot}}=\\sqrt5\\,\\mathrm{mm}\\approx2{,}24\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>.\nDie Grafiken zeigen einen erfundenen Punkt und Modellkurven.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_169_DE.svg\"\nalt=\"Schematische Punktquelle, breite und schmale Modell-Punktspreizfunktionen und beispielhafte Rauschbalken ohne Patientensignal.\" />\n<figcaption aria-hidden=\"true\">Schematische Punktquelle, breite und\nschmale Modell-Punktspreizfunktionen und beispielhafte Rauschbalken ohne\nPatientensignal.<\/figcaption>\n<\/figure>\n<p><em>Synthetische Bildqualitätskurven.<\/em><\/p>\n<p>Keine realen Detektordaten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist die relative Poisson-Unsicherheit bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=100<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>σ<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">\\sigma_{\\mathrm{tot}}<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_1=3\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_2=4\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum können rekonstruktionsbedingte Pixelkorrelationen die Formel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msqrt><mi>N<\/mi><\/msqrt><annotation encoding=\"application/x-tex\">\\sqrt N<\/annotation><\/semantics><\/math>\nungültig machen?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><msqrt><mn>100<\/mn><\/msqrt><mo>=<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/\\sqrt{100}=10\\,\\%<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>=<\/mo><msqrt><mrow><mn>9<\/mn><mo>+<\/mo><mn>16<\/mn><\/mrow><\/msqrt><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_{\\mathrm{tot}}=\\sqrt{9+16}\\,\\mathrm{mm}=5\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die Rekonstruktion kombiniert mehrere Messwerte und kann deren\nFehler räumlich korrelieren; ein Pixel ist dann keine unabhängige\nPoisson-Zählung.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Ortsinvarianz, Linearität und Gauß-Kerne sind Näherungen.\nUnterschiedliche Bildgebungsmodalitäten erfordern eigene physikalische\nVorwärtsmodelle, Qualitätsmetriken und Sicherheitsbewertung. Das\nDiagramm ist rein synthetisch.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Räumliche Auflösung, Rauschen und Kontrast sind nicht austauschbar.\nJede Bildverbesserung muss gegen Artefakte und Messbedingungen validiert\nwerden.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Strahlenschutz, Rechtfertigung und\nBildgebungsentscheidung<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://lme.tf.fau.de/lecture-notes/lecture-notes-me/computed-tomography-reconstruction/\">FAU – FAU Pattern Recognition Lab – Computed Tomography: Reconstruction<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Zeilen 55–87 und 102–103; Fachlicher Bezug zur Lektion: M24-L6 – Rekonstruktion, Auflösung, Rauschen und Artefakte · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://socr.umich.edu/BPAD1/BPAD1_notes/BPAD1_Chap06_NuclearMedicine_PET_SPECT.html\">University of Michigan – Biomedical Physics with Applications to Disease, Chapter 6: Nuclear Medicine, PET and SPECT<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Abschn. 6.4–6.5.2; Z. 439, 451–465; Fachlicher Bezug zur Lektion: M24-L6 – Rekonstruktion, Auflösung, Rauschen und Artefakte · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/3edwt-0rf59\">IAEA INIS – Diagnostic radiology physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–23; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L6 – Rekonstruktion, Auflösung, Rauschen und Artefakte · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M24-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M24-L7 – Strahlenschutz, Rechtfertigung und Bildgebungsentscheidung<\/h1>\n<p><strong>Kursbereich:<\/strong> M24 – Bachelor: Medizinische Physik und Bildgebung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlgebiet<\/p>\n<p><strong>Vorwissen:<\/strong> M15: Strahlungswechselwirkungen; M16:\nUnsicherheit; M24-L1: Dosisbegriffe. <a\nhref=\"index.html?course=university_physics&amp;module=M24&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Begriffe der diagnostischen Rechtfertigung\nund Optimierung erläutern und physikalische Dosis von klinischer\nBewertung trennen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Beobachtung<\/h2>\n<p>Nicht jede technisch mögliche Untersuchung ist medizinisch\ngerechtfertigt. Bei Untersuchungen mit ionisierender Strahlung sind\nklinischer Nutzen und mögliche Nachteile abzuwägen, bevor eine\nExposition durchgeführt wird. Danach sollen Aufnahmebedingungen so\noptimiert werden, dass die benötigte diagnostische Information bei\nangemessener Exposition gewonnen wird. Das ist keine Aufforderung, die\nDosis ohne Rücksicht auf die Bildaussage einfach gegen null zu\nreduzieren.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Gleichungen<\/h2>\n<p>Die absorbierte Dosis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>D<\/mi><annotation encoding=\"application/x-tex\">D<\/annotation><\/semantics><\/math>\nbeschreibt die lokal deponierte Energie pro Masse, die im SI als Gray\nangegeben wird. Schutzgrößen wie Organ- und effektive Dosis verwenden\nweitere physikalische und populationsbezogene Gewichtungen und sind\nnicht mit einer individuellen Risikoprognose gleichzusetzen. Die\ninternationale IAEA-Grundnorm unterscheidet die Rechtfertigung einer\nmedizinischen Exposition von der Optimierung des Strahlenschutzes. In\nder Bildgebung hängen technische Parameter von Fragestellung, Verfahren,\nPatienteneigenschaften und erforderlicher Bildqualität ab.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo>=<\/mo><mfrac><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">b<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mi>m<\/mi><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">J<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">k<\/mi><msup><mi mathvariant=\"normal\">g<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">D=\\frac{E_{\\mathrm{abs}}}{m},\\qquad 1\\,\\mathrm{Gy}=1\\,\\mathrm{J\\,kg^{-1}}.<\/annotation><\/semantics><\/math><\/p>\n<p>Röntgen und CT verwenden externe ionisierende Strahlung; PET und\nSPECT beruhen auf radioaktiven Tracern, deren Verteilung und\nAusscheidung die Exposition beeinflussen. MRT nutzt statische und\nzeitabhängige Magnetfelder und Hochfrequenz; Ultraschall nutzt\nmechanische Wellen. Das Fehlen ionisierender Strahlung bedeutet jedoch\nnicht, dass MRT oder Ultraschall ohne jegliche physikalische\nSicherheitsanforderungen betrieben werden könnten. Kontraindikationen,\nGeräteparameter und fachliche Sicherheitsleitlinien sind separat zu\nprüfen. Diese Lektion vermittelt keine klinische Handlungsanweisung.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Ein rein mechanisches Beispiel: Eine gedachte, gleichmäßige\nEnergieaufnahme von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">b<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>020<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">J<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E_{\\mathrm{abs}}=0{,}020\\,\\mathrm J<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">m=2{,}0\\,\\mathrm{kg}<\/annotation><\/semantics><\/math>\nentspricht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>010<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><mo>=<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">D=0{,}010\\,\\mathrm{Gy}=10\\,\\mathrm{mGy}<\/annotation><\/semantics><\/math>.\nDaraus folgen weder eine individuelle effektive Dosis in Sv noch eine\nDiagnostikempfehlung. Die Grafik zeigt einen abstrakten\nEntscheidungspfad von klinischer Fragestellung zu geeignetem Verfahren,\ndokumentierter Rechtfertigung, Optimierung und Qualitätskontrolle.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_171_DE.svg\"\nalt=\"Neutraler Entscheidungsfluss mit klinischer Fragestellung, Verfahrenswahl, Rechtfertigung, Optimierung und Qualitätsprüfung.\" />\n<figcaption aria-hidden=\"true\">Neutraler Entscheidungsfluss mit\nklinischer Fragestellung, Verfahrenswahl, Rechtfertigung, Optimierung\nund Qualitätsprüfung.<\/figcaption>\n<\/figure>\n<p><em>Eigenes konzeptionelles Qualitätssicherungsdiagramm; kein\nmedizinischer Entscheidungsalgorithmus.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>D<\/mi><annotation encoding=\"application/x-tex\">D<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">b<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>005<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">J<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E_{\\mathrm{abs}}=0{,}005\\,\\mathrm J<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{kg}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum ist der kleinste technisch erreichbare Dosiswert nicht immer\ndie sinnvollste Optimierungsgröße?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Verfahren nutzen selbst keine ionisierenden Röntgenphotonen:\nCT, MRT, Ultraschall, PET?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>005<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">y<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">D=0{,}005\\,\\mathrm{Gy}=5\\,\\mathrm{mGy}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die diagnostische Aufgabe verlangt eine ausreichende Bildaussage;\nbei zu wenigen Messereignissen kann das Ergebnis unbrauchbar\nwerden.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">MRT und Ultraschall; PET beruht auf radioaktiven Emissionen, CT auf\nRöntgenstrahlung.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die hier genannten Grundprinzipien ersetzen weder nationale\nVorschriften noch ärztliche Rechtfertigung, Strahlenschutzexpertise oder\ngerätespezifische Sicherheitsvorgaben. Beispielzahlen sind fiktiv und\nkeine Untersuchungsparameter.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Rechtfertigung beantwortet, warum untersucht wird; Optimierung, wie\neine bereits gerechtfertigte Untersuchung fachgerecht und mit geeigneter\nBildqualität umgesetzt wird.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://nucleus.iaea.org/sites/nss-oui/Published%20Collections/m_3761d926-c16f-4477-a63b-741a9db1c16c/m_3761d926-c16f-4477-a63b-741a9db1c16c__50_0.Html\">IAEA – IAEA International Basic Safety Standards<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Anforderungen 37–38, Abs. 3.155 und 3.163–3.164; Fachlicher Bezug zur Lektion: M24-L7 – Strahlenschutz, Rechtfertigung und Bildgebungsentscheidung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://nucleus.iaea.org/Pages/rpop.aspx\">IAEA NUCLEUS – Radiation Protection of Patients<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 32–38; thematische Quellenzuordnung; Fachlicher Bezug zur Lektion: M24-L7 – Strahlenschutz, Rechtfertigung und Bildgebungsentscheidung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://inis.iaea.org/records/3edwt-0rf59\">IAEA INIS – Diagnostic radiology physics: handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Z. 12–23; Metadaten; thematische Handbuchzuordnung, kein Formelnachweis; Fachlicher Bezug zur Lektion: M24-L7 – Strahlenschutz, Rechtfertigung und Bildgebungsentscheidung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
